    REQUIRE(h.last_req.find("\"note\":\"x-note\"") != std::string::npos);
    REQUIRE(h.last_req.find("\"offset\":42") != std::string::npos);
    REQUIRE(h.last_req.find("\"payload\":\"x-payload\"") != std::string::npos);
